// PWM/AXI mode switch test for KR260
// Hardware protocol taken from peristalsis_command_interface_wide S00_AXI:
//   REG0 (0x00): rom1[31:16], rom0[15:0]
//   REG1 (0x04): rom3[31:16], rom2[15:0]
//   REG2 (0x08): stroke_left[31:16], stroke_right[15:0]
//   REG3 (0x0c): stroke_down[31:16], stroke_up[15:0]
//   REG4 (0x10): control_mode[16], read-only done[15], start[14], stick3[13:7], stick1[6:0]
// No cmd_start pulses are generated by this test program.

#include <cerrno>
#include <chrono>
#include <atomic>
#include <array>
#include <cstdint>
#include <cstdlib>
#include <cstring>
#include <fcntl.h>
#include <iomanip>
#include <iostream>
#include <limits>
#include <sstream>
#include <stdexcept>
#include <string>
#include <sys/mman.h>
#include <thread>
#include <unistd.h>

namespace {
constexpr uintptr_t COMMAND_BASE = 0xA0010000UL;
constexpr size_t MAP_SIZE = 4096;
constexpr size_t REG_ROM_L = 0;
constexpr size_t REG_ROM_H = 1;
constexpr size_t REG_STROKE_L = 2;
constexpr size_t REG_STROKE_H = 3;
constexpr size_t REG_CMD = 4;
constexpr uint32_t START = 1U << 14;
constexpr uint32_t DONE = 1U << 15;
constexpr uint32_t PWM_MODE = 1U << 16;

class AxiRegs {
public:
    explicit AxiRegs(bool dry) : dry_(dry) {
        if (dry_) {
            std::cout << "[DRY-RUN] no /dev/mem access, no motor control\n";
            return;
        }
        fd_ = ::open("/dev/mem", O_RDWR | O_SYNC);
        if (fd_ < 0) throw std::runtime_error(std::string("open /dev/mem: ") + std::strerror(errno));
        void *p = ::mmap(nullptr, MAP_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd_, COMMAND_BASE);
        if (p == MAP_FAILED) {
            const auto err = std::string("mmap: ") + std::strerror(errno);
            ::close(fd_);
            fd_ = -1;
            throw std::runtime_error(err);
        }
        ptr_ = static_cast<volatile uint32_t*>(p);
    }
    ~AxiRegs() {
        if (!dry_ && ptr_) ::munmap(const_cast<uint32_t*>(ptr_), MAP_SIZE);
        if (fd_ >= 0) ::close(fd_);
    }
    AxiRegs(const AxiRegs&) = delete;
    AxiRegs& operator=(const AxiRegs&) = delete;

    uint32_t read(size_t idx) const { return dry_ ? fake_[idx] : ptr_[idx]; }
    void write(size_t idx, uint32_t value) {
        if (dry_) {
            fake_[idx] = value;
            std::cout << "[DRY-RUN] REG" << idx << " <= 0x" << std::hex << value << std::dec << '\n';
        } else {
            ptr_[idx] = value;
        }
    }
    bool pwm_enabled() const { return (read(REG_CMD) & PWM_MODE) != 0; }
    uint16_t rom2() const { return static_cast<uint16_t>(read(REG_ROM_H) & 0xffffU); }
    uint16_t rom3() const { return static_cast<uint16_t>((read(REG_ROM_H) >> 16) & 0xffffU); }

    void set_rom23(unsigned value) {
        // Disable changes while PWM is enabled; these affect the NEXT motion cycle.
        if (pwm_enabled()) throw std::runtime_error("Switch to AXI mode before changing ROM.");
        const uint32_t packed = ((value & 0xffffU) << 16) | (value & 0xffffU);
        write(REG_ROM_H, packed);
        if (rom2() != value || rom3() != value) throw std::runtime_error("ROM readback mismatch");
    }

    void set_pwm_mode(bool pwm) {
        // Do not write START or the read-only DONE bit back. Preserve stick fields.
        uint32_t value = read(REG_CMD) & ~(START | DONE | PWM_MODE);
        if (pwm) value |= PWM_MODE;
        write(REG_CMD, value);
        std::this_thread::sleep_for(std::chrono::milliseconds(20));
        if (pwm_enabled() != pwm) throw std::runtime_error("control_mode readback mismatch");
    }

    void status() const {
        const auto cmd = read(REG_CMD);
        const auto rom_l = read(REG_ROM_L);
        const auto rom_h = read(REG_ROM_H);
        const auto stro_l = read(REG_STROKE_L);
        const auto stro_h = read(REG_STROKE_H);
        std::cout << "\n[AXI register status]\n"
                  << "  REG0 ROM01 = 0x" << std::hex << std::setw(8) << std::setfill('0') << rom_l << '\n'
                  << "  REG1 ROM23 = 0x" << std::setw(8) << rom_h << std::dec << std::setfill(' ') << '\n'
                  << "  ROM2 = " << rom2() << ", ROM3 = " << rom3() << "\n"
                  << "  REG2 stroke right/left = 0x" << std::hex << std::setw(8) << std::setfill('0') << stro_l << '\n'
                  << "  REG3 stroke up/down    = 0x" << std::setw(8) << stro_h << '\n'
                  << "  REG4 command/status    = 0x" << std::setw(8) << cmd << std::dec << std::setfill(' ') << '\n'
                  << "  mode = " << (cmd & PWM_MODE ? "PWM (1)" : "AXI (0)")
                  << ", start = " << ((cmd & START) ? 1 : 0)
                  << ", done(read bit15) = " << ((cmd & DONE) ? 1 : 0) << "\n"
                  << "  Note: no PWM stick position or BUSY register is exposed to PS yet.\n\n";
    }

private:
    bool dry_ = false;
    int fd_ = -1;
    volatile uint32_t *ptr_ = nullptr;
    uint32_t fake_[5]{};
};

// Matches the previously working peri_collect_unified initialization.
// DO NOT write these registers while a motor is energized: target_raw
// changes can immediately affect the wire_set target when that path is active.
class InitialSettings {
public:
    static constexpr uintptr_t WIRE_BASE = 0xA0020000UL;
    static constexpr uintptr_t DEADBAND_BASE = 0xA0040000UL;
    static constexpr std::array<uint32_t, 4> TARGET_RAW{{725U, 3453U, 2700U, 267U}};
    static constexpr uint32_t DEAD_MANUAL = 5U;
    static constexpr uint32_t DEAD_AUTO = 20U;

    explicit InitialSettings(bool dry) : wire_(WIRE_BASE, dry), dead_(DEADBAND_BASE, dry) {}

    void show() const {
        std::cout << "[Wire setting 0xA0020000]\n";
        for (size_t i=0; i<TARGET_RAW.size(); ++i) {
            const auto value = wire_.read(i) & 0xfffU;
            std::cout << "  target_raw" << i << " = " << value
                      << " (expected " << TARGET_RAW[i] << ")\n";
        }
        std::cout << "[Deadband 0xA0040000]\n"
                  << "  manual = " << (dead_.read(0) & 0x3fU) << " (expected 5)\n"
                  << "  auto   = " << (dead_.read(1) & 0x3fU) << " (expected 20)\n"
                  << "  setup  = " << (matches() ? "PASS" : "NOT CONFIGURED / MISMATCH") << "\n\n";
    }

    bool matches() const {
        for (size_t i=0; i<TARGET_RAW.size(); ++i) {
            if ((wire_.read(i) & 0xfffU) != TARGET_RAW[i]) return false;
        }
        return (dead_.read(0) & 0x3fU) == DEAD_MANUAL &&
               (dead_.read(1) & 0x3fU) == DEAD_AUTO;
    }

    void apply(const AxiRegs& cmd) {
        if (cmd.pwm_enabled()) throw std::runtime_error("Cannot write setup in PWM mode. First stop the robot and switch to AXI.");
        if ((cmd.read(REG_CMD) & START) != 0) throw std::runtime_error("START is asserted; cannot change setup.");
        for (size_t i=0; i<TARGET_RAW.size(); ++i) wire_.write(i, TARGET_RAW[i] & 0xfffU);
        dead_.write(0, DEAD_MANUAL);
        dead_.write(1, DEAD_AUTO);
        std::atomic_thread_fence(std::memory_order_seq_cst);
        if (!matches()) throw std::runtime_error("Initialization readback mismatch. Do NOT enable motor power.");
    }

private:
    class RegisterBlock {
    public:
        explicit RegisterBlock(uintptr_t address, bool dry): dry_(dry) {
            if (dry_) return;
            fd_ = ::open("/dev/mem", O_RDWR | O_SYNC);
            if (fd_ < 0) throw std::runtime_error(std::string("open /dev/mem: ") + std::strerror(errno));
            void* p = ::mmap(nullptr, MAP_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd_, address);
            if (p == MAP_FAILED) {
                const auto message = std::string("mmap settings: ") + std::strerror(errno);
                ::close(fd_);
                fd_ = -1;
                throw std::runtime_error(message);
            }
            regs_ = static_cast<volatile uint32_t*>(p);
        }
        ~RegisterBlock() {
            if (regs_) ::munmap(const_cast<uint32_t*>(regs_), MAP_SIZE);
            if (fd_ >= 0) ::close(fd_);
        }
        RegisterBlock(const RegisterBlock&) = delete;
        RegisterBlock& operator=(const RegisterBlock&) = delete;
        uint32_t read(size_t idx) const { return dry_ ? fake_[idx] : regs_[idx]; }
        void write(size_t idx, uint32_t v) {
            if (dry_) {
                fake_[idx] = v;
                std::cout << "[DRY-RUN] setup reg[" << idx << "] <= " << v << '\n';
            } else regs_[idx] = v;
        }
    private:
        bool dry_ = false;
        int fd_ = -1;
        volatile uint32_t* regs_ = nullptr;
        std::array<uint32_t, 4> fake_{};
    };
    RegisterBlock wire_;
    RegisterBlock dead_;
};

bool confirm(const std::string& message, const std::string& expected) {
    std::cout << message << "\nType " << expected << " to confirm: " << std::flush;
    std::string answer;
    return static_cast<bool>(std::getline(std::cin, answer)) && answer == expected;
}

void help() {
    std::cout << "Commands:\n"
              << "  status     : read REG0..REG4, display ROM2/ROM3 and mode\n"
              << "  rom N      : write ROM2=ROM3=N (1..3000) while AXI mode, e.g. rom 100\n"
              "  setup      : write target_raw[0..3]=725,3453,2700,267 and deadband=5,20\n"
              "  settings   : read target_raw and deadband registers (read-only)\n"
              << "  pwm        : switch to PWM mode (receiver controls the forward cycles)\n"
              << "  axi        : switch back to AXI after R-stick neutral + motion stopped\n"
              << "  quit       : exit program (only allowed after mode=AXI)\n"
              << "  help       : show these commands\n";
}

unsigned parse_rom(const std::string &arg) {
    size_t end = 0;
    const auto result = std::stoul(arg, &end, 10);
    if (end != arg.size() || result < 1 || result > 3000)
        throw std::invalid_argument("ROM must be an integer 1..3000");
    return static_cast<unsigned>(result);
}

} // namespace

int main(int argc, char** argv) {
    const bool dry = argc == 2 && std::string(argv[1]) == "--dry-run";
    if (argc > 1 && !dry) {
        std::cerr << "Usage: " << argv[0] << " [--dry-run]\n";
        return 2;
    }
    try {
        AxiRegs axi(dry);
        InitialSettings settings(dry);
        std::cout << "\nperi_pwm_mode_test - PWM/AXI hardware switching test\n"
                  << "AXI base: 0xA0010000, REG4 bit16 = mode\n"
                  "Settings: wire=0xA0020000, deadband=0xA0040000\n"
                  << "NO start pulses are issued. NO posture reset is issued.\n"
                  << "PS does NOT read the analog posture in this PL version.\n"
                  << "\nWARNING: Ctrl+C or closing this app DOES NOT stop PL motion.\n"
                  << "If the R-stick stays UP in PWM mode, robot may continue moving.\n"
                  << "Have a physical motor power cutoff available. No other PS app may\n"
                  << "access the same registers concurrently.\n"
                  "IMPORTANT: use `setup` with MOTOR POWER OFF, then check `settings`.\n"
                  "Do NOT try wire_set until encoder readings and PWM inputs are verified.\n";
        help();
        axi.status();
        settings.show();
        std::string line;
        while (true) {
            std::cout << "pwm-test> " << std::flush;
            if (!std::getline(std::cin, line)) {
                std::cerr << "\nInput closed. This DOES NOT change PL mode or stop motion.\n";
                break;
            }
            try {
                std::istringstream in(line);
                std::string cmd, extra;
                in >> cmd;
                if (cmd.empty()) continue;
                if (cmd == "help") help();
                else if (cmd == "status") { axi.status(); settings.show(); }
                else if (cmd == "settings") settings.show();
                else if (cmd == "setup") {
                    if (axi.pwm_enabled()) { std::cerr << "Refusing setup in PWM mode.\n"; continue; }
                    if (confirm("MOTOR POWER MUST BE OFF. Receiver sticks NEUTRAL; toggle not enabling motion.\n"
                                "Will write target_raw=725,3453,2700,267 and deadband=5,20.\n"
                                "These are values from the previously working PS program.\n"
                                "Confirm the same robot/encoder wiring is connected.", "SETUP")) {
                        settings.apply(axi);
                        std::cout << "Initialization verified by register readback.\n";
                        settings.show();
                    }
                }
                else if (cmd == "rom") {
                    std::string number;
                    if (!(in >> number) || (in >> extra)) { std::cerr << "Usage: rom 100\n"; continue; }
                    const auto n = parse_rom(number);
                    if (confirm("About to set ROM2=ROM3=" + std::to_string(n) + ". Compare against your verified motor setup.", "ROM")) {
                        axi.set_rom23(n);
                        axi.status();
                    }
                } else if (cmd == "pwm") {
                    if (axi.pwm_enabled()) { std::cout << "Already in PWM mode.\n"; continue; }
                    if (!settings.matches()) {
                        std::cerr << "target_raw/deadband do not match expected settings. With motor power OFF, run setup first.\n";
                        continue;
                    }
                    if (axi.rom2() == 0 || axi.rom3() == 0) {
                        std::cerr << "ROM2 or ROM3 is zero. Set a verified value first: rom 100\n";
                        continue;
                    }
                    std::cout << "PWM preflight: receiver bound, receiver toggle in LOW (normal command mode),\n"
                              << "RIGHT stick for FORWARD is NEUTRAL, posture stick centered (50).\n"
                              << "Make sure motors are clear and physical power-stop is ready.\n"
                              << "Do not hold R-stick UP while enabling PWM mode.\n";
                    if (confirm("Set REG4 bit16 to 1?", "PWM")) {
                        axi.set_pwm_mode(true);
                        std::cout << "PWM ENABLED. Operate the receiver to test posture+forward.\n"
                                  << "Return R-stick to neutral to stop starting NEW cycles.\n"
                                  << "An ACTIVE cycle may continue to finish. Use hardware stop in emergency.\n";
                        axi.status();
                    }
                } else if (cmd == "axi") {
                    if (!axi.pwm_enabled()) { std::cout << "Already in AXI mode.\n"; continue; }
                    std::cout << "IMPORTANT: AXI mode has a R-stick UP => test_global_shrink path.\n"
                              << "If R-stick remains UP when PWM is disabled, straight-test movement may restart!\n";
                    if (!confirm("Release R-stick to NEUTRAL, stop all motion, then confirm.", "CENTERED")) continue;
                    std::cout << "Waiting 8 seconds for any active cycle to finish.\n";
                    std::this_thread::sleep_for(std::chrono::seconds(8));
                    if (confirm("Re-check R-stick is NEUTRAL and robot is stationary. Switch to AXI?", "AXI")) {
                        axi.set_pwm_mode(false);
                        std::cout << "AXI mode restored. No posture-reset command has been issued.\n";
                        axi.status();
                    }
                } else if (cmd == "quit" || cmd == "exit") {
                    if (axi.pwm_enabled()) {
                        std::cout << "PWM is active. Use 'axi' only AFTER stick neutral and motion stops.\n"
                                  << "Ctrl+C/terminal close cannot guarantee a safe stop.\n";
                        continue;
                    }
                    std::cout << "Finished in AXI mode.\n";
                    return 0;
                } else {
                    std::cout << "Unknown command. Type 'help'.\n";
                }
            } catch (const std::exception& ex) {
                std::cerr << "Command failed: " << ex.what() << '\n';
            }
        }
        return axi.pwm_enabled() ? 3 : 0;
    } catch (const std::exception& ex) {
        std::cerr << "Error: " << ex.what() << '\n';
        return 1;
    }
}
